// Values from the data table codebot_settings
const setting = (k, fallback) => {
  const v = String($input.all().map(i => i.json).find(r => r.key === k)?.value ?? '').trim() || fallback;
  if (!v) throw new Error(`${k} is missing in codebot_settings`);
  return v;
};
const timezone = setting('timezone');
if (!DateTime.now().setZone(timezone).isValid) throw new Error(`timezone in codebot_settings is not a valid IANA time zone: ${timezone}`);
// ==== ADJUST HERE ====
return [{ json: {
  CHAT_ID: setting('telegram_chat_id'),
  CALENDAR_ID: setting('calendar_id'),   // the events are created here
  TIMEZONE: timezone,

  DEADLINE_DAYS: 45,                    // deadlines within this period go into the calendar

  // The orchestrator starts tickets with this label at Claude (CodeBot - Start Claude Routine).
  // The orchestrator ignores all other issues. CodeBot - Planning proposes planning sessions.
  CCR_LABEL: setting('ready_label', 'ready-for-agent'),
  MAX_CCR_PER_RUN: 3,                   // at most this many starts per run
}}];

const cfg = $('Config').first().json;
const tz = cfg.TIMEZONE;
const now = DateTime.now().setZone(tz);
const events = $('Calendar: Events').all().map(i => i.json).filter(e => e.id && e.status !== 'cancelled');
const rows = $('Projects').all().map(i => i.json).filter(r => r.key);
// Open issues of the repos in codebot_projects
const items = ($('GitHub').first().json.data?.search?.nodes || [])
  .filter(c => c && c.number && c.__typename === 'Issue')
  .map(c => ({ content: c }));

// Open predecessors: native GitHub dependencies, or else a line "Blocked by: #1, #2" in the issue text
const openBlockers = (i, openSet) => {
  const native = (i.blockedBy?.nodes || []).filter(b => b.state === 'OPEN').map(b => b.number);
  const line = (String(i.body || '').match(/^\s*Blocked by:\s*(.+)$/im) || [])[1] || '';
  const fromBody = [...line.matchAll(/#(\d+)/g)].map(m => Number(m[1])).filter(n => openSet.has(n));
  return [...new Set([...native, ...fromBody])];
};
// Open PRs per repo, recognised by the branch claude/issue-<N>-… (in addition to the link through "Closes #N")
const branchPrs = {};
for (const r of Object.values($('GitHub').first().json.data || {})) {
  if (!r?.nameWithOwner) continue;
  branchPrs[r.nameWithOwner.toLowerCase()] = new Set((r.pullRequests?.nodes || [])
    .map(p => (String(p.headRefName || '').match(/^claude\/issue-(\d+)(?:-|$)/) || [])[1]).filter(Boolean).map(Number));
}
const eventKey = e => (String(e.description || '').match(/codebot-key:\s*(\S+)/) || [])[1] || null;
const existingKeys = new Set(events.map(eventKey).filter(Boolean));

// --- Projects from codebot_projects
const prioVal = { High: 3, Medium: 2, Low: 1 };
const projects = rows.map(r => ({
  key: r.key, current: r.next_block || null, name: r.name,
  repo: String(r.repo || '').trim().toLowerCase(), prio: r.priority || 'Medium', status: r.status,
  deadline: /^\d{4}-\d{2}-\d{2}/.test(String(r.deadline || '')) ? String(r.deadline) : null }));
const byRepo = Object.fromEntries(projects.filter(p => p.repo).map(p => [p.repo, p]));
const inactive = p => p && ['Paused', 'Done', 'Someday'].includes(p.status);

// --- Candidates from the open issues
const ccr = [];
const openByRepo = {};
for (const it of items) (openByRepo[it.content.repository.nameWithOwner.toLowerCase()] ||= new Set()).add(it.content.number);
for (const it of items) {
  const c = it.content;
  if (!c || c.state !== 'OPEN' || !c.repository) continue;
  const labels = (c.labels?.nodes || []).map(l => l.name);
  const repo = c.repository.nameWithOwner;
  const proj = byRepo[repo.toLowerCase()];
  if (!proj || inactive(proj)) continue;
  let score = prioVal[proj?.prio] || 1;
  if (proj?.deadline && DateTime.fromISO(proj.deadline).diff(now, 'days').days < 14) score += 3;
  if (labels.includes(cfg.CCR_LABEL)) {
    // Ticket for Claude: start only without an open PR and without open predecessors
    const hasPr = (c.closedByPullRequestsReferences?.nodes || []).some(p => p.state === 'OPEN')
      || (branchPrs[repo.toLowerCase()] || new Set()).has(c.number);
    const blocked = openBlockers(c, openByRepo[repo.toLowerCase()] || new Set()).length > 0;
    if (!hasPr && !blocked) ccr.push({ repo, issue: c, score });
    continue;
  }
  // Everything else (no label or a different one) is ignored.
}

const out = [];

// --- Deadlines from codebot_projects: all-day event + advance warning 3 days before
const allDay = (date, summary, description, key) => ({ json: {
  kind: 'event', key,
  label: `${date.setLocale('en').toFormat('ccc d LLL')} ${summary}`,
  summary, description: `${description}\ncodebot-key: ${key}`,
  start: date.set({ hour: 12 }).toISO(), end: date.plus({ days: 1 }).set({ hour: 12 }).toISO(),
  allday: 'yes', showMeAs: 'transparent',
} });
const today = now.startOf('day');
for (const p of projects) {
  if (!p.deadline || inactive(p)) continue;
  const date = DateTime.fromISO(p.deadline, { zone: tz }).startOf('day');
  const left = date.diff(today, 'days').days;
  if (left < 0 || left > cfg.DEADLINE_DAYS) continue;
  const key = `codebot-deadline:${p.key}:${date.toISODate()}`;
  if (!existingKeys.has(key)) out.push(allDay(date, `⏰ Deadline: ${p.name}`, 'Deadline from the project list.', key));
  const pre = date.minus({ days: 3 });
  const preKey = `codebot-deadline-pre:${p.key}:${date.toISODate()}`;
  if (pre >= today && !existingKeys.has(preKey))
    out.push(allDay(pre, `⏰ In 3 days: deadline ${p.name}`, `Deadline on ${date.toFormat('yyyy-MM-dd')}.`, preKey));
}
// --- Write the next planning session per project (from the calendar, scheduled through CodeBot - Planning) back to codebot_projects
const next = {};
const addBlock = (key, iso) => {
  const m = String(key || '').match(/^codebot-(?:issue|plan):([^#\s]+)/);
  const proj = m && byRepo[m[1].toLowerCase()];
  if (!proj) return;
  const d = DateTime.fromISO(iso).setZone(tz);
  if (d <= now) return;
  if (!next[proj.key] || d < next[proj.key].d) next[proj.key] = { d, proj };
};
for (const e of events) if (e.start?.dateTime) addBlock(eventKey(e), e.start.dateTime);
for (const { d, proj } of Object.values(next)) {
  const cur = proj.current ? DateTime.fromISO(proj.current).setZone(tz) : null;
  if (cur && Math.abs(cur.diff(d, 'minutes').minutes) < 1) continue; // unchanged
  out.push({ json: { kind: 'block', key: proj.key, date: d.toISO(), project: proj.name } });
}
// --- Jobs for Claude (the double-start guard lives in CodeBot - Start Claude Routine)
for (const w of ccr.sort((a, b) => b.score - a.score).slice(0, cfg.MAX_CCR_PER_RUN)) {
  out.push({ json: { kind: 'ccr', repo: w.repo, issue_number: w.issue.number, title: w.issue.title,
                     url: w.issue.url, body: w.issue.body || '', source: 'dev-orchestrator' } });
}
return out;

// Query GitHub only for the repos in codebot_projects (no account-wide search)
const rows = $('Projects').all().map(i => i.json).filter(r => r.key);
const repos = [...new Set(rows.map(r => String(r.repo || '').trim()).filter(r => /^[\w.-]+\/[\w.-]+$/.test(r)))];
if (!repos.length) return [{ json: { query: 'query { viewer { login } }', repos } }];
const repoParts = repos.map((r, i) => {
  const [o, n] = r.split('/');
  return `  r${i}: repository(owner: "${o}", name: "${n}") { nameWithOwner pushedAt pullRequests(states: OPEN, first: 50) { nodes { number headRefName } } }`;
});
const q = `is:open is:issue archived:false ${repos.map(r => 'repo:' + r).join(' ')}`;
const query = `query {
${repoParts.join('\n')}
  search(type: ISSUE, first: 100, query: "${q}") {
    nodes {
      ... on Issue { __typename number title url state body repository { nameWithOwner } labels(first: 10) { nodes { name } } blockedBy(first: 20) { nodes { number state } } closedByPullRequestsReferences(first: 5) { nodes { number state } } }
    }
  }
}`;
return [{ json: { query, repos } }];
